server {
  listen 8080;
  server_name _;

  # SearXNG clients (Hermes' searxng provider among them) hardcode
  # `/search?format=json`. Degoog serves the equivalent document at
  # `/api/search`. Rewrite transparently.
  location = /search {
    proxy_pass http://127.0.0.1:4444/api/search$is_args$args;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
  }

  # Everything else is Degoog's own surface, untouched.
  location / {
    proxy_pass http://127.0.0.1:4444;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
  }
}

server {
  listen 8080;
  server_name tesla.waltr.tech;
  root /usr/share/nginx/html;
  # Tesla Fleet API: exact path, no redirect handling
  location = /.well-known/appspecific/com.tesla.3p.public-key.pem {
    default_type application/x-pem-file;
    add_header Cache-Control "public, max-age=86400";
  }
}

import json, os, urllib.request

# name -> candidate URLs, tried in order until the content validates.
# A bare filename is not enough: upstream splits each voice across
# hosts, and a wrong host returns an LFS pointer (~130 bytes) or a
# 404 body rather than an error, which would land on disk and make
# piper fail at load.
SOURCES = {
    # Portal GLaDOS (itsdarklikehell/GLaDOS-TTS): the .onnx is a Git
    # LFS object, the .onnx.json is a plain git object.
    "en_US-glados-medium.onnx": [
        "https://media.githubusercontent.com/media/itsdarklikehell/GLaDOS-TTS/main/en_US-glados-medium.onnx",
        "https://raw.githubusercontent.com/itsdarklikehell/GLaDOS-TTS/main/en_US-glados-medium.onnx",
    ],
    "en_US-glados-medium.onnx.json": [
        "https://raw.githubusercontent.com/itsdarklikehell/GLaDOS-TTS/main/en_US-glados-medium.onnx.json",
    ],
    # Portal Wheatley (HuggingFace, fox3000foxy/piper-checkpoints-wheatley-en).
    "wheatley-en.onnx": [
        "https://huggingface.co/fox3000foxy/piper-checkpoints-wheatley-en/resolve/main/wheatley-en.onnx",
    ],
    "wheatley-en.onnx.json": [
        "https://huggingface.co/fox3000foxy/piper-checkpoints-wheatley-en/resolve/main/wheatley-en.onnx.json",
    ],
}
DST = "/data"

def valid(path, name):
    if not os.path.exists(path):
        return False
    size = os.path.getsize(path)
    if name.endswith(".onnx"):
        return size > 1_000_000  # an LFS pointer is ~130 bytes
    try:
        json.load(open(path))
        return True
    except Exception:
        return False

os.makedirs(DST, exist_ok=True)
for name, urls in SOURCES.items():
    dest = os.path.join(DST, name)
    if valid(dest, name):
        print("present:", name, os.path.getsize(dest))
        continue
    for url in urls:
        host = url.split("/")[2]
        try:
            print("fetching:", name, "from", host)
            urllib.request.urlretrieve(url, dest)
        except Exception as exc:
            print("  failed:", host, exc)
            continue
        if valid(dest, name):
            print("  got:", name, os.path.getsize(dest))
            break
        print("  rejected bad content from", host, os.path.getsize(dest))
    else:
        raise SystemExit(f"ERROR: could not fetch {name}")
print("voices ready:", sorted(os.listdir(DST)))
